/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Error_BadgeInputs */

const en_error_badge = /** @type {(inputs: Error_BadgeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Error`)
};

const zh_cn2_error_badge = /** @type {(inputs: Error_BadgeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`错误`)
};

const ja_error_badge = /** @type {(inputs: Error_BadgeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`エラー`)
};

/**
* | output |
* | --- |
* | "Error" |
*
* @param {Error_BadgeInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const error_badge = /** @type {((inputs?: Error_BadgeInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Error_BadgeInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_error_badge(inputs)
	if (locale === "ja") return ja_error_badge(inputs)
	return en_error_badge(inputs)
});