/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Notfound_BackhomeInputs */

const en_notfound_backhome = /** @type {(inputs: Notfound_BackhomeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Back home`)
};

const zh_cn2_notfound_backhome = /** @type {(inputs: Notfound_BackhomeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`回到家`)
};

const ja_notfound_backhome = /** @type {(inputs: Notfound_BackhomeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`家に帰ります`)
};

/**
* | output |
* | --- |
* | "Back home" |
*
* @param {Notfound_BackhomeInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const notfound_backhome = /** @type {((inputs?: Notfound_BackhomeInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Notfound_BackhomeInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_notfound_backhome(inputs)
	if (locale === "ja") return ja_notfound_backhome(inputs)
	return en_notfound_backhome(inputs)
});