/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Notfound_BodyInputs */

const en_notfound_body = /** @type {(inputs: Notfound_BodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`The page you are looking for doesn't exist or has moved.`)
};

const zh_cn2_notfound_body = /** @type {(inputs: Notfound_BodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`您要查找的页面不存在或已移动。`)
};

const ja_notfound_body = /** @type {(inputs: Notfound_BodyInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`お探しのページは存在しないか、移動されました。`)
};

/**
* | output |
* | --- |
* | "The page you are looking for doesn't exist or has moved." |
*
* @param {Notfound_BodyInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const notfound_body = /** @type {((inputs?: Notfound_BodyInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Notfound_BodyInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_notfound_body(inputs)
	if (locale === "ja") return ja_notfound_body(inputs)
	return en_notfound_body(inputs)
});