/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Notfound_TitleInputs */

const en_notfound_title = /** @type {(inputs: Notfound_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Page not found`)
};

const zh_cn2_notfound_title = /** @type {(inputs: Notfound_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`找不到页面`)
};

const ja_notfound_title = /** @type {(inputs: Notfound_TitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ページが見つかりません`)
};

/**
* | output |
* | --- |
* | "Page not found" |
*
* @param {Notfound_TitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const notfound_title = /** @type {((inputs?: Notfound_TitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Notfound_TitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_notfound_title(inputs)
	if (locale === "ja") return ja_notfound_title(inputs)
	return en_notfound_title(inputs)
});