import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Error_BackhomeInputs */

const en_error_backhome = /** @type {(inputs: Error_BackhomeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Back home`)
};

const zh_cn2_error_backhome = /** @type {(inputs: Error_BackhomeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`回到家`)
};

const ja_error_backhome = /** @type {(inputs: Error_BackhomeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`家に帰ります`)
};

/**
* | output |
* | --- |
* | "Back home" |
*
* @param {Error_BackhomeInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const error_backhome = /** @type {((inputs?: Error_BackhomeInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Error_BackhomeInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_error_backhome(inputs)
	if (locale === "ja") return ja_error_backhome(inputs)
	return en_error_backhome(inputs)
});